A form uses this JavaScript validation function:
function check(age) {
    if (age == "") {
        return "Required";
    }
    if (isNaN(age)) {
        return "Not a number";
    }
    if (age < 18 || age > 65) {
        return "Out of range";
    }
    return "OK";
}
