A web page contains:
<p id="count">2</p>
<button onclick="add()">Add</button>
<p id="msg"></p>
<script>
let c = 2;
function add() {
    c = c + 1;
    document.getElementById("count").innerHTML = c;
    if (c >= 3) {
        document.getElementById("msg").innerHTML = "Limit reached";
    }
}
</script>
